        stack: [{ name: "Cúram (Merative/IBM)", role: "Social Program Management", why: "Integrated eligibility determination for SNAP, Medicaid, TANF, and other programs. Designed for the rules-engine complexity of social programs. Used by multiple state HHS agencies.", href: "/vendors" }, { name: "Salesforce Government Cloud", role: "Case Management", why: "Citizen relationship management connecting benefits enrollment, case management, and interaction history across programs.", href: "/vendors/ccaas" }],
